import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G), G['Demo pair 1 input'].shape if hasattr(G['Demo pair 1 input'],'shape') else len(G))

import json
def transform(g):
    h=len(g); w=len(g[0])
    # find separator rows (full rows of one color) and separator cols
    sep_r=[r for r in range(h) if len(set(g[r]))==1]
    sep_c=[c for c in range(w) if len({g[r][c] for r in range(h)})==1]
    sep_col=g[sep_r[0]][sep_c[0]]
    # band row ranges
    def bands(seps,n):
        out=[];prev=0
        for s in seps+[n]:
            if s>prev: out.append((prev,s))
            prev=s+1
        return out
    rb=bands(sep_r,h); cb=bands(sep_c,w)
    # find template: the 4x4 block whose shape is not a solid 2x2 square
    tmpl=None
    for (r0,r1) in rb:
        for (c0,c1) in cb:
            blk=[row[c0:c1] for row in g[r0:r1]]
            cells={(i,j) for i in range(r1-r0) for j in range(c1-c0) if blk[i][j] not in (0,sep_col)}
            if cells and not (len(cells)==4):
                tmpl=cells; tcol=g[r0+min(i for i,j in cells)][c0+min(j for i,j in cells) if False else 0] # placeholder
                # get color
                colors={blk[i][j] for i,j in cells}
                tcol=list(colors)[0]
    assert tmpl
    out=[row[:] for row in g]
    for bi,(r0,r1) in enumerate(rb):
        # band color: from any existing 2x2 square in this band
        bcol=None
        for (c0,c1) in cb:
            blk=[row[c0:c1] for row in g[r0:r1]]
            cols={blk[i][j] for i in range(r1-r0) for j in range(c1-c0)}-{0,sep_col,tcol}
            if cols: bcol=list(cols)[0]; break
        for (c0,c1) in cb:
            for i in range(r1-r0):
                for j in range(c1-c0):
                    out[r0+i][c0+j]= bcol if (i,j) in tmpl else (sep_col if g[r0+i][c0+j]==sep_col and (i==0 or j==0) else 0)
    return out
